// 0 = not visited, 1 = on the current DFS path, 2 = finished
function hasCycle(v: number, adj: number[][], state: number[]): boolean {
	state[v] = 1;
	for (const w of adj[v]) {
		if (state[w] === 1) return true; // back edge: w is an ancestor of v
		if (state[w] === 0 && hasCycle(w, adj, state)) return true;
		// state[w] === 2: already finished, reached by another path, no cycle
	}
	state[v] = 2;
	return false;
}

// 0 = not visited, 1 = on the current DFS path, 2 = finished
function hasCycle(v: number, adj: number[][], state: number[]): boolean {
	state[v] = 1;
	for (const w of adj[v]) {
		if (state[w] === 1) return true; // back edge: w is an ancestor of v
		if (state[w] === 0 && hasCycle(w, adj, state)) return true;
		// state[w] === 2: already finished, reached by another path, no cycle
	}
	state[v] = 2;
	return false;
}
